"""Signature checks for the event requests Corvid Payments sends us."""

import base64
import hashlib
import hmac
import re

_T_RE = re.compile(r"[0-9]+")
_V2_RE = re.compile(r"[0-9a-f]{64}")


def _header(headers, name):
    """Case-insensitive header lookup; None when absent."""
    wanted = name.lower()
    for key, value in headers.items():
        if isinstance(key, str) and key.lower() == wanted:
            return value
    return None


def _parse_signature(value):
    """Returns (t, [v2, ...]) or None when the header does not parse."""
    t_values = []
    v2_values = []
    for element in value.split(","):
        element = element.lstrip(" ")
        key, sep, val = element.partition("=")
        if not sep or not key:
            return None
        if key == "t":
            t_values.append(val)
        elif key == "v2":
            v2_values.append(val)
        # v1 and any other scheme name are ignored.
    if len(t_values) != 1 or not v2_values:
        return None
    if not _T_RE.fullmatch(t_values[0]):
        return None
    if not all(_V2_RE.fullmatch(v) for v in v2_values):
        return None
    return t_values[0], v2_values


def _key(secret):
    """The HMAC key for a `whsec_...` secret, or None when it is not valid."""
    if not isinstance(secret, str) or not secret.startswith("whsec_"):
        return None
    try:
        return base64.b64decode(secret[len("whsec_"):].encode("ascii"), validate=True)
    except ValueError:
        return None


def verify(headers: dict[str, str], body: bytes, secrets: list[str], now: int) -> bool:
    """True when the request carries a valid Corvid signature, else False. Never raises.

    `headers` are the request headers, `body` the request body as received, `secrets` the
    signing secrets the receiver holds (`whsec_...`), `now` the current time in Unix seconds.
    """
    try:
        event_id = _header(headers, "Corvid-Event-Id")
        signature = _header(headers, "Corvid-Signature")
        if not isinstance(event_id, str) or not isinstance(signature, str):
            return False
        parsed = _parse_signature(signature)
        if parsed is None:
            return False
        t_text, candidates = parsed
        t = int(t_text)
        if t < now - 300 or t > now + 60:
            return False
        payload = b"v2:" + t_text.encode() + b":" + event_id.encode("utf-8") + b":" + bytes(body)
        ok = False
        for secret in secrets:
            key = _key(secret)
            if key is None:
                continue
            expected = hmac.new(key, payload, hashlib.sha256).hexdigest()
            for candidate in candidates:
                if hmac.compare_digest(expected.encode(), candidate.encode()):
                    ok = True
        return ok
    except Exception:
        return False
